<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Request; use App\Core\Response; use App\Core\Tenant; use App\Core\ForbiddenException; final class ModuleMiddleware { public function handle(Request $request,\Closure $next,?string $module=null):Response{if($module!==null&&!Tenant::hasModule($module))throw new ForbiddenException('This feature is not enabled for this school plan.');return $next($request);} }